from pathlib import Path
import re
root=Path(__file__).resolve().parent.parent
template=(root/'dist/about.html').read_text()
fields=[('id','Offer ID / shortlink','text',60),('retailer','Retailer','text',80),('department','Department (optional)','text',50),('title','Offer title','text',140),('description','Description (optional)','textarea',400),('discount','Discount or price','text',30),('code','Coupon code (optional)','text',80),('merchant_url','Retailer HTTPS link','url',1500),('conditions','Conditions and exclusions','textarea',1500),('expires_at','Expiry — your local time','datetime-local',40),('referral_beneficiary','Who benefits? (if a referral or commission)','text',120),('referral_reward','Reward and conditions (if applicable)','textarea',300)]
inputs=''
for key,label,kind,limit in fields:
 required='' if key in ['department','description','code','referral_beneficiary','referral_reward'] else ' required'
 control=f'<textarea id="c-{key}" name="{key}" maxlength="{limit}"{required}></textarea>' if kind=='textarea' else f'<input id="c-{key}" name="{key}" type="{kind}" maxlength="{limit}"{required}>'
 inputs+=f'<label for="c-{key}">{label}</label>'+control
inputs+='<label for="c-category">Category</label><select id="c-category" name="category"><option value="tech">Tech &amp; Hardware</option><option value="fashion">Fashion &amp; Retail</option><option value="food">Food &amp; Groceries</option><option value="other">Other</option></select><label class="consent"><input name="glitch" type="checkbox"> Pricing glitch — a reviewer must actually test the checkout</label><label class="consent"><input name="affiliate" type="checkbox"> Referral or commission link — disclosure required above</label>'
signin='''<section id="signin-panel"><h2>Your contribution. Your name.</h2><p>Reading and copying codes need no account. Sign in only to contribute. Your public name is shown with accepted edits; your email stays private.</p><form id="signin-form" class="alert-form"><label for="contributor-email">Email address</label><input id="contributor-email" type="email" name="email" autocomplete="email" required maxlength="254"><div id="community-security"></div><div class="desk-actions"><button name="intent" value="request">send.code_</button></div><label for="email-code">Code from your email</label><input id="email-code" name="token" inputmode="numeric" autocomplete="one-time-code" pattern="[0-9]{6,10}" maxlength="10"><button name="intent" value="verify">sign.in_</button></form></section>'''
profile='''<section id="profile-panel" hidden><h2>Pick your public name.</h2><p>Use a name you are comfortable keeping in the edit history. Do not use an email address, phone number or someone else’s identity.</p><form id="profile-form" class="alert-form"><label for="public-name">Public name</label><input id="public-name" name="handle" pattern="[a-z][a-z0-9_-]{2,31}" minlength="3" maxlength="32" required autocomplete="nickname"><label class="consent"><input type="checkbox" name="consent" required>I have read the <a href="/community-guide">contributor rules</a> and accept the published contribution terms.</label><button>create.profile_</button></form></section>'''
contribute=f'''<span class="eyebrow">FLUQON.QPON / COMMUNITY</span><h1>Find it. Check it.<br>Share it.</h1><p class="intro">Useful offers improve when people can correct them. Show the source. State the conditions. Leave the hype out.</p><aside id="community-stage" class="community-notice" role="status">Checking contribution availability…</aside><nav class="community-nav" aria-label="Community"><a href="/community-guide">How contributions work</a><a href="/history">history.fluq_</a><a href="/community-review">Review desk</a></nav>{signin}{profile}<div id="contributor-panel" hidden><p><span id="contributor-name" class="data"></span> <button id="signout" type="button" class="quiet-button">sign.out_</button></p><section><h2>New offer or correction?</h2><form id="load-form" class="inline-form"><label for="existing-offer">Existing offer ID</label><input id="existing-offer" name="id" pattern="[a-z0-9][a-z0-9-]{{2,59}}" maxlength="60" required><button>load.latest_</button></form><p>For a new offer, leave the loader alone and fill the form below. For a correction, load the latest revision first.</p><p id="base-revision" class="data">New offer · revision 0</p><form id="contribution-form" class="alert-form">{inputs}<label for="c-source">Source confirming the offer</label><input id="c-source" name="source_url" type="url" required maxlength="1500"><label for="c-summary">What are you adding or changing?</label><textarea id="c-summary" name="summary" minlength="10" maxlength="500" required></textarea><p>Do not include payment details, emails, order numbers or private screenshots. A submission is a proposal, not a verification badge.</p><div class="desk-actions"><button>submit.fluq_</button><button id="clear-draft" type="button" class="quiet-button">new.offer_</button></div></form></section><section><h2>Your submissions</h2><div id="my-proposals"></div></section><section><h2>Add a source note</h2><form id="note-form" class="alert-form"><label for="note-offer">Offer ID</label><input id="note-offer" name="offer_id" required pattern="[a-z0-9][a-z0-9-]{{2,59}}"><label for="note-body">Useful correction or evidence</label><textarea id="note-body" name="body" minlength="10" maxlength="1000" required></textarea><p>Notes are reviewed before appearing publicly. Keep personal details out.</p><button>submit.note_</button></form></section></div><p id="community-status" role="status" aria-live="polite" tabindex="-1"></p>'''
review='''<span class="eyebrow">FLUQON.QPON / REVIEW</span><h1>Clear evidence.<br>Useful changes.</h1><p class="intro">Compare the proposal, check the source, then make the call. Changes never approve themselves.</p><aside id="community-stage" class="community-notice" role="status">Checking review availability…</aside><nav class="community-nav" aria-label="Community"><a href="/contribute">Contribute</a><a href="/history">Public history</a><a href="/community-guide">Rules</a></nav><section id="review-login"><h2>Open the review desk</h2><p>Assigned reviewers can use their contributor session. The owner can use the existing operator key. Keys stay in this tab’s memory and are cleared when locked.</p><form id="review-key-form" class="alert-form"><label for="review-key">Owner key</label><input id="review-key" name="key" type="password" autocomplete="off" minlength="64" maxlength="64" required><button>unlock.fluq_</button></form><button id="review-session" class="quiet-button" type="button">use.contributor.session_</button></section><div id="review-panel" hidden><div class="desk-actions"><button id="refresh-queue" type="button">refresh.queue_</button><button id="lock-review" class="quiet-button" type="button">lock.fluq_</button></div><p id="queue-count" class="data"></p><section><h2>Offer changes</h2><div id="review-proposals"></div></section><section><h2>Discussion notes</h2><div id="review-notes"></div></section><section id="member-tools"><h2>Contributor access</h2><p>The owner alone assigns access. Public names do not grant permissions.</p><div id="member-list"></div></section><section><h2>Remove private or harmful history</h2><p>This suppresses the public revision and pauses the current offer if it matches. The private audit records why. Ordinary corrections use a new proposal instead.</p><form id="redact-form" class="alert-form"><label for="redact-offer">Offer ID</label><input id="redact-offer" name="id" required><label for="redact-revision">Revision</label><input id="redact-revision" name="revision" type="number" min="1" required><label for="redact-reason">Private reason</label><textarea id="redact-reason" name="reason" minlength="10" maxlength="1000" required></textarea><button>remove.public.revision_</button></form></section></div><p id="community-status" role="status" aria-live="polite" tabindex="-1"></p>'''
history='''<span class="eyebrow">FLUQON.QPON / HISTORY</span><h1>See what changed.</h1><p class="intro">Accepted revisions, sources and public contributors. Earlier prices and codes are historical records, not current offers.</p><aside id="community-stage" class="community-notice" role="status">Checking history availability…</aside><nav class="community-nav" aria-label="Community"><a href="/contribute">contribute.fluq_</a><a href="/community-guide">Contributor rules</a></nav><form id="history-form" class="inline-form"><label for="history-offer">Offer ID (the last part of /offers/…)</label><input id="history-offer" name="id" pattern="[a-z0-9][a-z0-9-]{2,59}" maxlength="60" required placeholder="retailer-offer"><button>show.history_</button></form><section id="history-list"></section><section><h2>Source notes</h2><div id="history-notes"></div></section><p id="community-status" role="status" aria-live="polite" tabindex="-1"></p>'''
guide='''<span class="eyebrow">FLUQON.QPON / CONTRIBUTING</span><h1>Bring the source.<br>Skip the noise.</h1><p class="intro">A useful contribution helps someone understand the actual offer.</p><aside class="community-notice">The source is open. Contributor sign-in stays closed until the live authentication checks pass.</aside><section><h2>What belongs here</h2><p>Australian offers with a retailer source, clear eligibility, exclusions and expiry. Explain who receives any referral reward or commission and what the shopper gets. Do not silently replace someone else’s referral link.</p></section><section><h2>How edits work</h2><ol><li>Sign in and choose a public name.</li><li>Add an offer or load the latest revision to correct it.</li><li>Describe the change and link the source.</li><li>A reviewer independently checks it before publication.</li></ol><p>Reading and copying codes still need no account. A contribution, vote or working link does not prove a code was accepted at checkout. Normal verification expires after 24 hours; glitches need an actual checkout check and expire after four.</p></section><section><h2>Public history</h2><p>Accepted edits retain a public name, dated change summary and source. Earlier revisions remain historical, even after prices change. Restoring an earlier version creates a new proposal and needs a fresh check. Maintainers can remove private or harmful material from public history.</p></section><section><h2>Respect the people doing the work</h2><p>No harassment, impersonation, spam or undisclosed paid placements. Explain disagreements with sources. New submissions and discussion notes await review. The owner can restrict access and protect pages.</p></section><section><h2>Your material and privacy</h2><p>Submit your own short factual wording. Link to retailer terms instead of copying their entire page. Never post personal details, payment information, emails, order numbers or private reports. Your email is used privately for contributor authentication; it does not subscribe you to marketing alerts.</p><p>Software uses AGPL-3.0-only. By submitting original offer text for inclusion, you license it under CC BY-SA 4.0, with your public name and change history retained. You keep ownership. Brand artwork, retailer material and private records are outside that content licence. Public registration stays closed until the live authentication checks pass.</p></section><section><h2>Help improve the software</h2><p>The <a href="https://github.com/valavaiau/fluqon-qpon">public source repository</a> includes setup instructions, tests and contribution guidelines. Code changes use pull requests and maintainer review. Report security issues privately through the documented security contact; do not post credentials or customer data in public issues.</p></section><p><a href="/contribute">contribute.fluq_</a> · <a href="/history">history.fluq_</a> · <a href="/privacy">Privacy</a></p>'''
for slug,title,main in [('contribute','Contribute',contribute),('community-review','Community review',review),('history','Offer history',history),('community-guide','Contributor rules',guide)]:
 page=re.sub(r'<main\b.*?</main>',f'<main class="support community" id="content" data-community-page="{slug}">{main}</main>',template,flags=re.S)
 page=re.sub(r'<title>.*?</title>',f'<title>{title} — fluqon.qpon</title>',page)
 page=page.replace('</head>','<meta name="robots" content="noindex,nofollow"><link rel="stylesheet" href="/forms.css"><link rel="stylesheet" href="/community.css"><script type="module" src="/community.js"></script></head>')
 page=re.sub(r'(property="og:title" content=")[^"]*',lambda m:m.group(1)+title+' — fluqon.qpon',page)
 page=re.sub(r'(name="twitter:title" content=")[^"]*',lambda m:m.group(1)+title+' — fluqon.qpon',page)
 page=re.sub(r'(name="description" content="|property="og:description" content="|name="twitter:description" content=")[^"]*',lambda m:m.group(1)+'Community offers, clear evidence and useful corrections.',page)
 page=re.sub(r'https://fluqon.qpon/about',f'https://fluqon.qpon/{slug}',page)
 (root/'dist'/f'{slug}.html').write_text(page)
# The frontend shares only validation and field names, never backend credentials or service logic.
(root/'dist/community-policy.mjs').write_text((root/'server/community-policy.mjs').read_text())
